/* --- Estrutura Geral --- */
.footer-section {
    background-color: #ffffff;
    border-top: 1px solid #e2e8f0; /* border-slate-200 */
    padding: 48px 0; /* py-12 */
    font-family: 'Inter', sans-serif;
}


.footer-section .container {
    max-width: 1280px; /* max-w-7xl */
    margin: 0 auto;
    padding: 0 16px;
}

/* --- Bloco Superior (Marca e Badges) --- */
.footer-top {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: space-between;
    gap: 32px;
    border-bottom: 1px solid #f1f5f9; /* border-slate-100 */
    padding-bottom: 32px; /* pb-8 */
}

@media (min-width: 768px) {
    .footer-top {
        flex-direction: row;
    }
}

/* Marca e Logo do Projeto */
.footer-brand {
    text-align: center;
}

@media (min-width: 768px) {
    .footer-brand {
        text-align: left;
    }
}

.project-logo {
    height: 40px; /* Altura padrão para a logo principal */
    width: auto;
    display: inline-block;
}

.brand-subtitle {
    font-size: 12px; /* text-xs */
    color: #64748b; /* text-slate-500 */
    margin: 4px 0 0 0;
}

/* Badges Laterais */
.footer-badges {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    justify-content: center;
    gap: 24px; /* gap-6 */
}

.badge-item {
    display: flex;
    align-items: center;
    gap: 8px; /* gap-2 */
    border: 1px solid #e2e8f0; /* border-slate-200 */
    padding: 6px 12px; /* py-1.5 px-3 */
    border-radius: 8px;
    background-color: #f8fafc; /* bg-slate-50 */
    font-size: 12px; /* text-xs */
    font-weight: 600;
    color: #94a3b8; /* text-slate-400 */
}

.badge-item i {
    color: #64748b; /* text-slate-500 */
}

/* --- Bloco do Meio: Logos das Instituições --- */
.footer-institutions {
    padding: 32px 0;
    border-bottom: 1px solid #f1f5f9;
    text-align: center;
}

.institutions-title {
    font-size: 11px;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    color: #94a3b8;
    margin: 0 0 20px 0;
    font-weight: 600;
}

.logos-grid {
    display: flex;
    flex-wrap: wrap;
    justify-content: center;
    align-items: center;
    gap: 48px; /* Espaçamento largo entre logos */
}

.inst-logo {
    height: 45px; /* Altura controlada para manter as 3 logos proporcionais */
    width: auto;
    max-width: 150px;
    object-fit: contain;
    filter: grayscale(100%); /* Mantém uma estética sóbria de rodapé acadêmico */
    opacity: 0.7;
    transition: all 0.3s ease;
}

.inst-logo:hover {
    filter: grayscale(0%); /* Mostra as cores originais ao passar o mouse */
    opacity: 1;
}

/* --- Bloco Inferior (Direitos e Contato) --- */
.footer-bottom {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: space-between;
    font-size: 12px; /* text-xs */
    color: #64748b; /* text-slate-500 */
    padding-top: 32px; /* pt-8 */
    gap: 16px;
}

@media (min-width: 640px) {
    .footer-bottom {
        flex-direction: row;
    }
}

.footer-bottom p {
    margin: 0;
    font-size: 12px; /* text-xs */
}

.footer-links {
    display: flex;
    gap: 16px;
}

.contact-link {
    color: #64748b;
    text-decoration: none;
    display: inline-flex;
    align-items: center;
    gap: 4px;
    transition: color 0.2s ease;
}

.contact-link:hover {
    color: #0369a1; /* text-ecoiot-dark */
}

